#top {
  position: absolute;
  height: 0;
  width: 0;
  top: 0;
}

.top-link {
  width: calc(var(--baseline) * 4);
  height: calc(var(--baseline) * 4);
  background: var(--main-color);
  position: fixed !important;
  bottom: var(--padding);
  right: var(--padding);
  transition: all 0.3s ease;
  -webkit-border-radius: 50%;
  -moz-border-radius: 50%;
  border-radius: 50%;
  z-index: 100;
  border: 2px solid var(--white);
  display: flex;
  align-items: center;
  align-content: center;
}
.top-link:hover {
  -webkit-border-radius: 5px;
  -moz-border-radius: 5px;
  border-radius: 5px;
}
.top-link p {
  font-weight: 700;
  text-align: center;
  color: var(--white);
  margin: 0;
  padding: 0;
  font-size: 1rem;
  line-height: 1;
  width: 100%;
}

body.top .top-link {
  opacity: 0;
  visibility: hidden;
}

body.scroll .top-link {
  opacity: 1;
  visibility: visible;
}

.loader {
  display: block;
  width: 100%;
  height: 100%;
  position: fixed;
  top: 0;
  right: 0;
  bottom: 0;
  left: 0;
  background: var(--white);
  z-index: 109;
  opacity: 1;
  -webkit-border-radius: 0;
  -moz-border-radius: 0;
  border-radius: 0;
  scale: 1;
  transition: transform 0.15s ease-in, opacity 0.15s ease-in, filter 0.15s ease-in;
}
.loader img.loader-logo {
  display: block;
  width: 100px;
  height: auto;
  position: absolute;
  top: 50%;
