:root {
  --font-size: 0.875rem;
}
@media screen and (min-width: 576px) {
  :root {
    --font-size: calc(0.875rem + 0.125 * (100vw - 576px) / 824);
  }
}
@media screen and (min-width: 1400px) {
  :root {
    --font-size: 1rem;
  }
}

html {
  font-size: var(--font-size);
}

.p {
  font-size: var(--p);
  line-height: calc(var(--p) * 1.7);
}

.h1 {
  font-size: var(--h1);
  line-height: calc(var(--h1) * 1.5);
}

.h2 {
  font-size: var(--h2);
  line-height: calc(var(--h2) * 1.5);
}

.h3 {
  font-size: var(--h3);
  line-height: calc(var(--h3) * 1.5);
