.slider-wrapper {
  width: 100%;
  position: relative;
}
.slider-wrapper i.slider-controls {
  position: absolute;
  top: 50vh;
  transform: translateY(-50%);
  font-size: 52px;
  height: 56px;
  width: 56px;
  background: var(--main-color);
  box-shadow: 0 3px 6px rgba(0, 0, 0, 0.23);
  border-radius: 50%;
  cursor: pointer;
  line-height: 32px;
  text-align: center;
  transition: 0.3s ease;
  z-index: 3;
  padding: 2px;
  color: var(--white);
}
.slider-wrapper i.slider-controls:first-child {
  left: var(--margin);
}
.slider-wrapper i.slider-controls:last-child {
  right: var(--margin);
}
.slider-wrapper i.slider-controls:active {
  transform: translateY(-50%) scale(0.85);
}
.slider-wrapper .slider {
  display: grid;
  grid-auto-flow: column;
  grid-auto-columns: 100%;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  scroll-behavior: smooth;
  margin: 0;
  padding: 0;
}
.slider-wrapper .slider.no-transition {
  scroll-behavior: auto;
}
.slider-wrapper .slider.dragging {
  scroll-behavior: auto;
  scroll-snap-type: none;
}
.slider-wrapper .slider.dragging .card {
  user-select: none;
  cursor: grab;
}
.slider-wrapper .slider .slide {
  scroll-snap-align: start;
  width: 100%;
  display: flex;
  height: 100%;
  overflow: hidden;
  position: relative;
  margin: 0;
  padding: 0;
}
.slider-wrapper .slider .slide > .img, .slider-wrapper .slider .slide > .wp-block-image {
  position: absolute;
  display: block;
  top: 0;
  right: 0;
  bottom: 0;
  left: 0;
  z-index: 0;
}
.slider-wrapper .slider .slide > .img img, .slider-wrapper .slider .slide > .wp-block-image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.slider-wrapper .slider .slide > .caption {
  position: absolute;
  display: block;
  top: 0;
  right: 0;
  bottom: 0;
  left: 0;
  z-index: 0;
}
.slider-wrapper .slider .slide.active > .caption {
  position: relative;
}

#black-layer {
  position: fixed;
  z-index: 900;
  bottom: 0;
  right: 0;
  width: 100vw;
  height: 100vh;
  background-color: rgba(0, 0, 0, 0.85);
  transition: all 0.25s ease-in;
}
#black-layer.gone {
  opacity: 0;
  width: 0;
  height: 0;
  background-color: rgba(0, 0, 0, 0);
  border-top-left-radius: 100%;
}

#consent-banner {
  position: fixed;
  z-index: 901;
  top: auto;
  bottom: 0;
  left: auto;
  width: 75%;
  -webkit-box-shadow: 0 0 0 3px rgba(0, 0, 0, 0.25);
  -moz-box-shadow: 0 0 0 3px rgba(0, 0, 0, 0.25);
  box-shadow: 0 0 0 3px rgba(0, 0, 0, 0.25);
  transition: transform 0.3s ease, box-shadow 0.3s ease;
  right: 10%;
  display: flex;
  flex-flow: row wrap;
  padding: calc(var(--padding) * 1.5);
  transform: translate(0, calc(var(--padding) * 0.25));
  background: var(--gingerbread);
  -webkit-border-top-left-radius: 15px;
  -webkit-border-top-right-radius: 15px;
  -moz-border-radius-topleft: 15px;
  -moz-border-radius-topright: 15px;
  border-top-left-radius: 15px;
  border-top-right-radius: 15px;
}
@media only screen and (min-width: 768px) {
  #consent-banner {
    width: 50%;
  }
}
#consent-banner:hover {
  transform: translate(0, 0);
  -webkit-box-shadow: 0 0 10px 3px rgba(0, 0, 0, 0.25);
  -moz-box-shadow: 0 0 10px 3px rgba(0, 0, 0, 0.25);
  box-shadow: 0 0 10px 3px rgba(0, 0, 0, 0.25);
}
#consent-banner a.close-cookie-banner {
  position: absolute;
  top: calc(var(--padding) * 2);
  right: calc(var(--padding) * 2);
  display: inline-block;
  line-height: 1;
  text-align: center;
  vertical-align: middle;
  font-size: var(--h4);
  color: var(--white) !important;
  padding: 0;
}
#consent-banner a.close-cookie-banner:hover {
  color: var(--black) !important;
}
#consent-banner p.cookie-icon {
  width: 50px;
  height: auto;
  display: block;
  margin: 0;
  text-align: left;
  font-size: var(--h1);
  line-height: calc(var(--h1) * 1.25);
}
@media only screen and (min-width: 768px) {
  #consent-banner p.cookie-icon {
    width: 60px;
  }
}
@media only screen and (min-width: 992px) {
  #consent-banner p.cookie-icon {
    width: 80px;
  }
}
#consent-banner .cookie-banner-content {
  width: calc(100% - 50px);
}
@media only screen and (min-width: 768px) {
  #consent-banner .cookie-banner-content {
    width: calc(100% - 60px);
  }
}
@media only screen and (min-width: 992px) {
  #consent-banner .cookie-banner-content {
    width: calc(100% - 80px);
  }
}
#consent-banner .cookie-banner-content .consent-label {
  display: block;
  margin-bottom: var(--margin);
}
#consent-banner .cookie-banner-content .consent-label p.cookie-desc {
  margin-top: 0;
  padding-right: 40px;
}
#consent-banner .cookie-banner-content .consent-label p.cookie-desc a {
  color: var(--white) !important;
  text-decoration: underline;
}
#consent-banner .cookie-banner-content .consent-label p.cookie-desc a:hover {
  color: var(--black) !important;
}
#consent-banner .cookie-banner-content p.consent-status {
  display: none;
  font-size: calc(var(--p) * 0.8);
  line-height: calc(var(--h3) * 1.5);
  margin: 0 calc(var(--margin) * 0.5);
}
#consent-banner.mini {
  position: absolute;
  padding: calc(var(--padding) * 0.5);
  transform: none;
  width: auto;
  cursor: pointer;
}
#consent-banner.mini .close-cookie-banner {
  display: none;
}
#consent-banner.mini p.cookie-icon {
  width: auto;
  font-size: var(--h3);
  line-height: calc(var(--h3) * 1.5);
}
#consent-banner.mini .cookie-banner-content {
  width: auto;
}
#consent-banner.mini .cookie-banner-content .consent-label {
  display: none;
}
#consent-banner.mini .cookie-banner-content .consent-buttons {
  display: none;
}
#consent-banner.mini .cookie-banner-content p.consent-status {
  display: inline-block;
  color: var(--white);
  font-weight: 700;
  font-style: italic;
}

#debug-box {
  position: fixed;
  z-index: 999;
  bottom: 0;
  right: 0;
  left: 0;
  text-align: right;
  border-left: 2px solid var(--black);
  display: flex;
  flex-flow: column wrap;
  align-items: start;
  padding: 0;
  max-width: 50%;
}
@media (min-width: 768px) {
  #debug-box {
    bottom: 0;
    border-bottom: 2px solid var(--black);
    border-left: none;
    flex-flow: row wrap;
    padding: 0 calc(var(--padding) * 0.5);
    max-width: none;
  }
