  #debug-box .debug-data {
    margin-bottom: 0;
    margin-right: calc(var(--margin) * 0.5);
  }
}
#debug-box .debug-data p {
  display: block;
  background: var(--black);
  padding: calc(var(--padding) * 0.5) calc(var(--padding) * 0.75);
  text-align: center;
  width: auto;
  line-height: 1;
}
@media (min-width: 768px) {
  #debug-box .debug-data p {
    margin: calc(var(--margin) * 0.25) calc(var(--margin) * 0.25) 0 calc(var(--margin) * 0.25);
  }
