.dev-tag {
  position: fixed;
  bottom: 0;
  right: 0;
  transform: rotate(-45deg) translate(15px, 30px);
  transform-origin: center;
  width: 80px;
  height: 40px;
  z-index: 999;
  box-shadow: 0 0 0 3px rgba(0, 0, 0, 0.05);
  transition: all 0.3s ease;
}
.dev-tag p {
  padding: calc(var(--margin) * 0.5);
  color: #fff;
  margin: 0;
  text-align: center;
  font-size: calc(var(--p) * 0.75);
  line-height: 1;
  font-weight: 700;
}
