#msg #errors, #msg #warnings {
  padding: calc(var(--padding) * 0.5) var(--padding);
  margin: calc(var(--margin) * 0.5) 0;
  transition: transform 0.3s ease;
  transform: translate(0, 0);
}
#msg #errors ul, #msg #warnings ul {
  list-style: none;
  margin: 0;
  padding: 0;
}
#msg #errors.minified, #msg #warnings.minified {
  transform: translate(calc(100% - var(--padding)), 0);
}
#msg #errors.minified:hover, #msg #warnings.minified:hover {
